1. {
2.   "$schema": "https://json-schema.org/draft/2020-12/schema",
3.   "$id": "https://goobers.dev/schemas/result.schema.json",
4.   "title": "ResultEnvelope",
5.   "description": "The V0 stage result envelope the runner acts on; consumed by gates and telemetry (ARCHITECTURE.md §5). Bulk outputs are artifact pointers; outputs carries scalars only.",
6.   "type": "object",
7.   "additionalProperties": false,
8.   "required": ["status"],
9.   "properties": {
10.     "status": { "type": "string", "enum": ["success", "failure", "blocked", "no-work"] },
11.     "outputs": {
12.       "type": "object",
13.       "description": "Small declared scalar values only. Anything larger is an artifact, referenced by pointer — state does not travel through outputs.",
14.       "additionalProperties": {
15.         "type": ["string", "number", "integer", "boolean", "null"]
16.       }
17.     },
18.     "artifacts": {
19.       "type": "array",
20.       "items": { "$ref": "artifact-pointer.schema.json" }
21.     },
22.     "transcript": {
23.       "description": "Runner-captured transcript for this agentic attempt. Diagnostic only; unlike artifacts, it is not passed to downstream stages.",
24.       "$ref": "artifact-pointer.schema.json"
25.     },
26.     "summary": { "type": "string" },
27.     "metrics": {
28.       "type": "object",
29.       "additionalProperties": { "type": "number" }
30.     },
31.     "error": { "$ref": "#/$defs/errorInfo" }
32.   },
33.   "allOf": [
34.     {
35.       "comment": "A failure result must carry error detail.",
36.       "if": {
37.         "properties": { "status": { "const": "failure" } },
38.         "required": ["status"]
39.       },
40.       "then": { "required": ["error"] }
41.     }
42.   ],
43.   "$defs": {
44.     "errorInfo": {
45.       "type": "object",
46.       "additionalProperties": false,
47.       "required": ["code", "message"],
48.       "properties": {
49.         "code": { "type": "string", "minLength": 1 },
50.         "message": { "type": "string", "minLength": 1 },
51.         "retryable": { "type": "boolean" }
52.       }
53.     }
54.   }
55. }
56.

